def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in g for v in row if v != 0}
    for color in colors:
        # Find triangular outlines whose two sides are uninterrupted diagonal runs.
        for r in range(h):
            for c in range(w):
                if g[r][c] != color:
                    continue
                for dr in (-1, 1):
                    # From a vertex, both diagonal sides extend in the same vertical direction.
                    rr = r + dr
                    while 0 <= rr < h and 0 <= c-(rr-r) < w and 0 <= c+(rr-r) < w:
                        d = rr-r
                        if g[rr][c-d] != color or g[rr][c+d] != color:
                            break
                        for cc in range(c-d+1, c+d):
                            if g[rr][cc] == 0:
                                g[rr][cc] = 2
                        rr += dr
    return g
